// Feedback describes observed responses. It does not infer a calibrated ability.
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const levels = ['A1','A2','B1','B2','C1'];

export function buildFeedback(attempt, questions, language = 'ru') {
  const t = (ru,en) => language === 'ru' ? ru : en;
  const domain = key => ({language:t('Грамматика и лексика','Grammar & vocabulary'), reading:t('Чтение','Reading'), listening:t('Аудирование','Listening')})[key];
  const bank = new Map(questions.map(question => [question.id,question]));
  const rows = attempt.answers.map(answer => ({answer,question:bank.get(answer.itemId)})).filter(row=>row.question);
  const topic = question => language === 'en' ? question.subskillEn : question.subskill;
  const explanation = question => language === 'en' ? question.explanationEn : question.explanation;
  const selected = ({answer,question}) => answer.response === null ? t('Не знаю','I don’t know') : question.options[answer.response];
  const missed = rows.filter(row => !row.answer.correct).sort((a,b)=>a.question.level-b.question.level);
  const targets = ['language','reading','listening'].map(key=>missed.find(row=>row.question.domain===key) || rows.find(row=>row.question.domain===key)).filter(Boolean);
  const focus = targets.map(({question})=>`${domain(question.domain)}: ${topic(question)}`).join(' · ');
  const languageTarget = targets.find(row=>row.question.domain==='language');
  const readingTarget = targets.find(row=>row.question.domain==='reading');
  const listeningTarget = targets.find(row=>row.question.domain==='listening');
  const reference = row => row ? `“${topic(row.question)}” (${row.question.id})` : t('короткий материал по интересной вам теме','a short piece on a topic you enjoy');
  const days = [
    [t('Разберите ответы','Understand your answers'),t(`Откройте разбор ниже. Начните с ${missed.length ? 'двух неверных ответов' : 'двух заданий, в которых вы были не уверены'}. Запишите: что выбрали, что подсказал текст и почему верен другой вариант.`, `Open the answer review below. Start with ${missed.length ? 'two incorrect answers' : 'two tasks you felt less sure about'}. Write down your choice, the evidence in the task, and the reason for the correct answer.`),t('Проверка: можете объяснить ответ своими словами, не глядя в разбор.','Self-check: explain the answer in your own words without looking at the explanation.')],
    [t('Примените языковую конструкцию','Use a language pattern'),t(`Возьмите тему ${reference(languageTarget)}. Прочитайте объяснение, придумайте 5 своих примеров и измените в каждом время, лицо или ситуацию. Не копируйте предложение из теста.`,`Use ${reference(languageTarget)}. Read the explanation, write 5 examples of your own, and change the time, person, or situation in each. Avoid copying the test sentence.`),t('Проверка: на следующий день восстановите 3 примера по памяти; спорные примеры покажите преподавателю.','Self-check: recreate 3 examples from memory the next day; ask your teacher about uncertain examples.')],
    [t('Найдите доказательство в тексте','Find evidence in a text'),t(`Вернитесь к ${reference(readingTarget)}. Выделите предложение, которое поддерживает ответ. Затем прочитайте новый короткий текст и запишите его главную мысль и 2 детали.`,`Return to ${reference(readingTarget)}. Identify the sentence that supports the answer. Then read a new short text and write down its main point and 2 details.`),t('Проверка: для каждого вывода найдите слова автора, а не только своё предположение.','Self-check: point to the author’s words for each conclusion, rather than relying only on your assumption.')],
    [t('Сопоставьте звук и смысл','Connect sound and meaning'),listeningTarget?t(`Послушайте запись ${listeningTarget.question.id} в разборе без текста. Запишите главную мысль и 3 ключевых слова. Прослушайте ещё раз, затем проверьте себя по расшифровке.`,`Replay ${listeningTarget.question.id} in the review without reading its transcript. Note the main point and 3 key words. Listen again, then check the transcript.`):t('Аудирование пока не оценено. Пройдите полную онлайн-часть со звуком или выберите короткую запись с расшифровкой и сопоставьте то, что услышали, с текстом.','Listening has not been assessed. Try the full online route with audio, or choose a short recording with a transcript and compare what you heard with the text.'),t('Проверка: отметьте, что мешало — незнакомое слово, слитное произношение или потеря общей мысли.','Self-check: note what was difficult — an unknown word, connected speech, or losing the main idea.')],
    [t('Подготовьте образец речи','Prepare a speaking sample'),t('Запишите 1–2 минуты о своей обычной неделе или недавнем решении. Добавьте причину и пример. Не заучивайте текст. Сохраните запись для разговора с преподавателем.','Record 1–2 minutes about your usual week or a recent decision. Include a reason and an example. Do not memorise a script. Keep the recording for your teacher conversation.'),t('Проверка: отметьте места, где было трудно продолжить мысль. Это материал для обсуждения, не оценка уровня.','Self-check: mark places where it was difficult to continue your thought. This is material for discussion, not a level score.')],
    [t('Подготовьте образец письма','Prepare a writing sample'),t('Без переводчика напишите сообщение другу: предложите план выходного дня и объясните выбор. Если это легко, сравните две идеи и обсудите их недостатки. Сохраните первую версию.','Without a translator, write a message to a friend suggesting a weekend plan and explaining your choice. If that feels easy, compare two ideas and discuss their drawbacks. Keep your first draft.'),t('Проверка: перечитайте отдельно содержание и форму. Запишите 2 вопроса преподавателю о своём тексте.','Self-check: review meaning and form separately. Write 2 questions for your teacher about your draft.')],
    [t('Перенесите навык в новую задачу','Transfer the skill to a new task'),t('Выберите новый текст или запись похожей сложности. Повторите приём с третьего или четвёртого дня. Сравните, что удаётся самостоятельно, а где ещё нужна опора.','Choose a new text or recording of similar difficulty. Repeat the method from day three or four. Compare what you can do independently and where you still need support.'),t('Проверка: не используйте повторный балл по уже знакомым вопросам как доказательство роста уровня.','Self-check: do not treat a higher score on familiar questions as proof of a higher level.')],
  ];
  const planHeading = t('Ваша первая неделя практики','Your first week of practice');
  const planIntro = t('Задания ниже опираются на ваши ответы. Это стартовый план для самостоятельной работы; один неверный ответ ещё не означает устойчивый пробел.','These activities use your responses as a starting point. They are a starter plan for independent practice; a single mistake does not establish a persistent weakness.');
  const html = `<section class="feedback-section" aria-labelledby="practice-heading"><p class="section-kicker">${t('ИЗ РЕЗУЛЬТАТА В ДЕЙСТВИЕ','FROM RESULTS TO ACTION')}</p><h2 id="practice-heading">${planHeading}</h2><p class="feedback-intro">${planIntro}</p><div class="practice-focus"><strong>${t('Темы из вашей попытки','Topics from your attempt')}</strong><p>${escape(focus)}</p></div><div class="practice-days">${days.map(([title,task,check],index)=>`<details ${index===0?'open':''}><summary><span class="day-number">${String(index+1).padStart(2,'0')}</span><span>${title}</span><span class="expand-symbol" aria-hidden="true">+</span></summary><div class="day-body"><p>${escape(task)}</p><p class="self-check">${escape(check)}</p></div></details>`).join('')}</div></section><section class="feedback-section" aria-labelledby="review-heading"><p class="section-kicker">${t('ПОНИМАНИЕ ВАЖНЕЕ БАЛЛА','UNDERSTANDING BEYOND THE SCORE')}</p><h2 id="review-heading">${t('Разбор ваших ответов','Your answer review')}</h2><p class="feedback-intro">${t('Откройте любое задание: ваш выбор, правильный ответ и объяснение. Задания этой версии после разбора будут вам знакомы — повторная попытка не является независимой проверкой.','Open any task to see your choice, the correct answer, and an explanation. After this review, these tasks will be familiar — a repeat attempt is not an independent assessment.')}</p><div class="answer-review">${rows.map((row,index)=>{const {answer,question}=row;return `<details class="review-item"><summary><span class="review-status ${answer.correct?'correct':'revisit'}" aria-label="${answer.correct?t('Верно','Correct'):t('Повторить','Review')}">${answer.correct?'✓':'↻'}</span><span><small>${String(index+1).padStart(2,'0')} / ${domain(question.domain)}</small>${escape(topic(question))}</span><span class="expand-symbol" aria-hidden="true">+</span></summary><div class="review-body">${question.passage?`<blockquote lang="en">${escape(question.passage)}</blockquote>`:''}${question.transcript?`<audio controls preload="none" src="${escape(question.audio)}" aria-label="${t('Запись','Recording')} ${index+1}"></audio><details class="transcript"><summary>${t('Показать расшифровку','Show transcript')}</summary><p lang="en">${escape(question.transcript)}</p></details>`:''}<p class="review-prompt" lang="en">${escape(question.prompt)}</p><p><span class="answer-caption">${t('Ваш ответ','Your answer')}</span><span lang="en">${escape(selected(row))}</span></p><p><span class="answer-caption">${t('Правильный ответ','Correct answer')}</span><strong lang="en">${escape(question.options[question.answer])}</strong></p><p class="review-explanation">${escape(explanation(question))}</p><small class="item-reference">${escape(question.id)} · ${t('авторская метка сложности','author-assigned difficulty')}: ${levels[question.level]} · ${t('ещё не откалибрована','not calibrated yet')}</small></div></details>`;}).join('')}</div></section>`;
  const text = [planHeading,planIntro,focus,'',...days.flatMap(([title,task,check],index)=>[`${index+1}. ${title}`,task,check,'']),t('РАЗБОР ОТВЕТОВ','ANSWER REVIEW'),...rows.flatMap((row,index)=>[`${index+1}. ${row.question.id} — ${topic(row.question)}`,row.question.passage||row.question.transcript||'',row.question.prompt,`${t('Ваш ответ','Your answer')}: ${selected(row)}`,`${t('Правильный ответ','Correct answer')}: ${row.question.options[row.question.answer]}`,explanation(row.question),''])].join('\n');
  return {html,text};
}

export function evidenceNote(info,language='ru') {
  const t=(ru,en)=>language==='ru'?ru:en;
  if(!info.assessed)return '';
  if(info.evidenceStatus==='insufficient')return t('Ответов пока недостаточно для устойчивого ориентира. Уровень нужно уточнить дополнительными заданиями.','There is not enough consistent evidence for a level estimate. Additional tasks are needed.');
  if(info.belowFloor)return t('Базовые задания в этой попытке пока не выполнены. Это повод проверить основы вместе с преподавателем.','The foundational tasks were not demonstrated in this attempt. Review the basics with your teacher.');
  const row=info.evidenceByLevel?.find(row=>row.level===info.level);
  const support=row?t(`На авторской сложности ${row.label}: ${row.correct} из ${row.total} верно.`, `At author-assigned ${row.label} difficulty: ${row.correct} of ${row.total} correct.`):'';
  const pending=info.upperBoundaryPending?t(` ${levels[info.upperBoundaryLevel]} требует дополнительных заданий — верхняя граница ещё не подтверждена.`,` ${levels[info.upperBoundaryLevel]} needs further tasks — the upper boundary is not established.`):'';
  return support+pending;
}
